    public int getLastMoment(int n, int[] left, int[] right) {
        ArrayList<Obj> objList = new ArrayList<>();

        // 初始化
        for (Integer ele : left) {
            objList.add(new Obj(ele, 0));
        }
        for (Integer ele : right) {
            objList.add(new Obj(ele, 1));
        }

        // 　计时启动
        int result = 0;
        while (objList.size() > 0) {
            // 检测是否出现会相遇的情况
            for (Obj ele : objList) {
                // 检测是否有相遇情况
                meetPro(objList, ele);
            }

            Iterator<Obj> iterator = objList.iterator();
            // 遍历蚂蚁
            while (iterator.hasNext()) {
                Obj obj = iterator.next();

                // 无相遇情况的移动处理
                if (!obj.hasChange) {
                    if (obj.des == 0) { // 向左
                        if (obj.index == 0) {
                            iterator.remove();
                        } else {
                            obj.index = obj.index - 1;
                        }
                    } else { // 向右
                        if (obj.index == n) {
                            iterator.remove();
                        } else {
                            obj.index = obj.index + 1;
                        }
                    }
                }
            }

            if (objList.size() != 0) {
                for (Obj ele : objList) {
                    if (ele.hasChange) {
                        ele.hasChange = false;
                    }
                }
                result = result + 1;
            } else {
                return result;
            }
        }

        return result;
    }

    private void meetPro(ArrayList<Obj> objList, Obj obj) {
        // 已经处理过的不能再次处理
        if (!obj.hasChange) {
            // 遍历查找是否有符合的相遇元素
            for (Obj ele : objList) {
                if (obj.des == 0) { // 向左的找向右元素
                    if (!ele.hasChange && ele.index == obj.index - 1 && ele.des == 1) {
                        ele.des = 0;
                        ele.hasChange = true;
                        obj.des = 1;
                        obj.hasChange = true;
                        break;
                    }
                } else {
                    if (!ele.hasChange && ele.index == obj.index + 1 && ele.des == 0) {
                        ele.des = 1;
                        ele.hasChange = true;
                        obj.des = 0;
                        obj.hasChange = true;
                        break;
                    }
                }
            }
        }
    }

    private static class Obj {
        Integer index;
        Integer des; // 0 向左(-1) , 1 向右(+1)
        boolean hasChange = false;

        public Obj(Integer index, Integer des) {
            this.index = index;
            this.des = des;
        }
    }
}

