        virtual ~StorageLayer() {}

        virtual void save(const std::string& key, const std::string& value) = 0;
        virtual std::string load(const std::string& key) const = 0;
}

class InMemoryStorageLayer : public StorageLayer {
public:
    InMemoryStorageLayer() : map_(std::make_unique<std::map<std::string, std::string>>()) {}

    void save(const std::string& key, const std::string& value) override {
        map_->insert(std::make_pair(key, value));
    }

    std::string load(const std::string& key) const override {
        auto it = map_->find(key);
        if (it == map_->end()) {
            return "";
        }
        return it->second;
    }

private:
    std::unique_ptr<std::map<std::string, std::string>> map_;
};

